//! Independent original source-seven, then immutable whole original Auto/Deps.
pub use dq_analyze::{sem,tree,scopes,pat,util,reactive_facts,raw_marker_policy,lint,parity,incr,gens,pat_match};
#[path="../../dmb/shared/test_scratch.rs"]mod test_scratch;
#[path="support/deps_original/reaction_producer.rs"]pub mod original_reaction;mod lints{pub use crate::original_reaction as derived_reads;}
#[path="support/deps_original/projected.rs"]mod deps;#[path="support/auto_generator_original/projected.rs"]mod auto_tracked;
use std::{collections::BTreeSet,path::{Path,PathBuf,Component},io::{self,Write}};
const ROLES:[&str;7]=["sparse_slots","system_accessors","stats","actions","declare_ids","declare","ui_types"];
fn document(name:&str,filename:&str,body:&str)->String{let mut text=format!("// GENERATED by tools/analyze: `analyze gen {}`. Do not edit by hand; edit the declarations it reads.\n// Written to code/engine/_generated/{}; not committed: every build regenerates it (`analyze gen`).\n\n",name,filename);text.push_str(body);if !text.ends_with('\n'){text.push('\n')}text}
fn engine(root:&Path)->Result<dq_analyze::run::Engine,String>{dq_analyze::run::Engine::new(dq_analyze::run::registry(),dq_analyze::run::Options{root:root.to_path_buf(),scopes_from:Some(root.to_path_buf()),lints:vec!["sem/keys".into()],raw:true,no_cache:true,..Default::default()})}
fn safe_write(root:&Path,relative:&str,text:&str)->io::Result<()>{let relative=Path::new(relative);if relative.is_absolute()||relative.components().any(|p|matches!(p,Component::ParentDir|Component::RootDir|Component::Prefix(_))){return Err(io::Error::new(io::ErrorKind::InvalidInput,"oracle generator output escapes private scratch"))}let target=root.join(relative);std::fs::create_dir_all(target.parent().ok_or_else(||io::Error::other("output parent absent"))?)?;let mut file=std::fs::OpenOptions::new().create_new(true).write(true).open(target)?;file.write_all(text.as_bytes())}
fn legacy_file_of(sem:&sem::Sem,location:dreammaker::Location)->Option<&str>{if location.is_builtins(){None}else{let relative=sem.rel(location);(!relative.is_empty()).then_some(relative)}}
fn legacy_canonical_read_key(kind:&sem::reads::ReadKind,name:&str,keys:&BTreeSet<String>,defines:&BTreeSet<String>)->String{if *kind==sem::reads::ReadKind::Accessor&&keys.contains(name){format!("capkey:[{name}]")}else if *kind==sem::reads::ReadKind::Accessor&&defines.contains(name){format!("[{name}]")}else{name.to_owned()}}
fn main()->Result<(),Box<dyn std::error::Error>>{
 use sha1::Digest as _;let immutable:[u8;20]=sha1::Sha1::digest(include_bytes!("support/auto_generator_original/producer.rs")).into();assert_eq!(immutable,[220,132,94,56,9,27,27,99,212,1,231,246,152,124,50,118,113,102,145,36],"immutable whole original Auto producer changed");
 let original=include_str!("support/auto_generator_original/producer.rs");let expected=original.replace("sem.file_of(p.get().location)","crate::legacy_file_of(&sem,p.get().location)").replace("sem.file_of(rel)","crate::legacy_file_of(&sem,rel)").replace("sem.file_of(loc)","crate::legacy_file_of(&sem,loc)").replace("sem.file_of(v.location)","crate::legacy_file_of(&sem,v.location)");assert_eq!(include_str!("support/auto_generator_original/projected.rs"),expected,"only private file lookup transport differs from immutable whole old producer");

 dq_analyze::sem::incremental::disable_capture();let fixture=PathBuf::from(std::env::args().nth(1).ok_or("Auto fixture root required")?);let configured=std::env::args().nth(2).as_deref()==Some("configured");let fixture=if fixture.is_absolute(){fixture}else{std::env::current_dir()?.join(fixture)};let root=dm_preprocess::regions::canonical_path(&test_scratch::dir("original-generation-auto"));std::fs::create_dir_all(root.join("code/tests"))?;std::fs::create_dir_all(root.join("tools/ci"))?;for relative in ["code/probe.dm","code/tests/only.dm"]{std::fs::copy(fixture.join(relative),root.join(relative))?;}std::fs::write(root.join("code/extra.dm"),"// actual uncompiled source, borrowed only by raw policy\n")?;if configured{std::fs::copy(fixture.join("tools/ci/lint_scopes.toml"),root.join("tools/ci/lint_scopes.toml"))?;}let mut manifest=String::new();let registry=dq_analyze::sem::gen::registry();for name in ["sparse_slots","system_accessors","stats","actions","declare_ids","declare","tracked_lists","deps","auto_tracked","reads","plans"]{let generator=registry.iter().find(|g|g.name()==name).ok_or("actual registered manifest output missing")?;manifest.push_str(&format!("#include \"{}/{}\"\n",dq_analyze::sem::gen::OUT_DIR,generator.output()));}manifest.push_str("#include \"code/_generated/reads.dm\"\n");manifest.push_str(&std::fs::read_to_string(fixture.join("deepquarry.dme"))?);std::fs::write(root.join("deepquarry.dme"),manifest)?;
 let registry=dq_analyze::sem::gen::registry();let initial=engine(&root)?;let mut staged=Vec::new();
 // ALL seven judge the SAME initial tree. Writes start only after their loans
 // end; no native output or answer is supplied to this independent recipe.
 for name in ROLES{let generator=registry.iter().find(|g|g.name()==name).ok_or("original source producer absent")?;let cx=dq_analyze::sem::gen::GenCx::new(&initial.tree,&root);let mut output=dq_analyze::sem::gen::GenOut::default();generator.generate(&cx,&mut output);let files=if generator.output().is_empty(){generator.files(&cx,&mut output)}else{vec![(format!("{}/{}",dq_analyze::sem::gen::OUT_DIR,generator.output()),document(generator.name(),generator.output(),output.text()))]};
  if !output.diags.is_empty(){return Err(format!("original source-seven findings: {:?}",output.diags.iter().map(|d|(&d.rel,d.line,&d.msg)).collect::<Vec<_>>()).into())}let wire=serde_json::json!({"generator":name,"files":&files,"diagnostics":[]});println!("OLD_AUTO_BOOTSTRAP_SOURCE_FILE={wire}");staged.push(files);
 }drop(initial);
 for files in staged{for(relative,text)in files{safe_write(&root,&relative,&text)?;}}
 let current=engine(&root)?;let observed=sem::ObservedGenerationOmissions::probe(&root)?;if observed.paths().next().is_none(){return Err("actual purpose outputs must remain missing after source seven".into())}let owner=sem::generation_original_for(&current.tree,observed)?;if !owner.errors.is_empty(){return Err(format!("partial original parser errors: {:?}",owner.errors).into())}
 let warm=sem::sem_for(&current.tree).ok_or("partial original owner loan unavailable")?;assert!(std::ptr::eq(&*owner,&*warm),"frozen Auto/Deps must share the same real old owner");drop(warm);
 let inferred=auto_tracked::inferred(&current.tree);let set=inferred.as_ref().as_ref().ok_or("whole original AutoTracked result unavailable")?;if set.tracked.is_empty(){return Err("whole original fixture must actually generate tracking".into())}
 let mut registry=Vec::new();auto_tracked::register(&mut registry);let generator=registry.iter().find(|value|value.name()=="auto_tracked").ok_or("whole original generator missing")?;let mut out=sem::gen::GenOut::default();generator.generate(&sem::gen::GenCx::new(&current.tree,&root),&mut out);let mut text=format!("// GENERATED by tools/analyze: \x60analyze gen {}\x60. Do not edit by hand; edit the declarations it reads.\n// Written to code/engine/_generated/{}; not committed: every build regenerates it (\x60analyze gen\x60).\n\n",generator.name(),generator.output());text.push_str(out.text());if !text.ends_with('\n'){text.push('\n')}
 println!("OLD_GENERATION_AUTO_FULL={}",serde_json::to_string(&serde_json::json!({"path":format!("code/engine/_generated/{}",generator.output()),"text":text,"diagnostics":out.diags.iter().map(|value|(&value.rel,value.line,&value.msg)).collect::<Vec<_>>()}))?);println!("OLD_GENERATION_AUTO_DECISIONS={}",serde_json::to_string(&serde_json::json!({"tracked":set.tracked.iter().map(|row|(&row.ty,&row.var,row.list)).collect::<Vec<_>>(),"blocked":set.blocked}))?);Ok(())
}
